import 'package:flutter/material.dart';
import 'package:flutter/semantics.dart';

import '../../../../core/design_tokens.dart';
import '../../../../core/widgets/app_button.dart';
import '../../domain/repositories/vault_repository.dart';

/// `/vault` — the epic's one lock screen, shown whenever
/// `VaultRepository.currentStatus` isn't `VaultStatus.unlocked`
/// (`core/navigation/app_router.dart`'s `_redirect`). Auto-triggers the OS
/// biometric prompt once in [initState]; a successful
/// [VaultRepository.authenticate] call flips `currentStatus` to `unlocked`,
/// which — via `statusStream`/`refreshListenable` — re-runs the redirect and
/// navigates away from here on its own, so this widget never navigates
/// imperatively itself. No PIN entry UI (Story 2.2).
class VaultLockScreen extends StatefulWidget {
  const VaultLockScreen({required this.vaultRepository, super.key});

  final VaultRepository vaultRepository;

  @override
  State<VaultLockScreen> createState() => _VaultLockScreenState();
}

class _VaultLockScreenState extends State<VaultLockScreen> {
  bool _authenticating = false;
  bool _showRetry = false;

  @override
  void initState() {
    super.initState();
    _attemptAuthenticate();
  }

  Future<void> _attemptAuthenticate() async {
    if (_authenticating) {
      return;
    }
    setState(() {
      _authenticating = true;
      _showRetry = false;
    });

    final result = await widget.vaultRepository.authenticate();
    if (!mounted) {
      return;
    }

    // On success, `currentStatus` is already `unlocked` and the router's
    // own `refreshListenable` will navigate away from `/vault` on its own —
    // this widget has nothing further to do (and may already be in the
    // process of being disposed by the time that happens).
    result.match(
      (_) => setState(() {
        _authenticating = false;
        _showRetry = true;
      }),
      (_) => setState(() {
        _authenticating = false;
      }),
    );

    // `Semantics(liveRegion: true)` below is primarily honored by Android's
    // TalkBack; this app is iOS-only, where VoiceOver doesn't reliably treat
    // a live-region subtree update as an announcement. `sendAnnouncement()`
    // is honored on both platforms, so the failure transition is still
    // spoken even if the live-region flag alone isn't.
    if (_showRetry && mounted) {
      await SemanticsService.sendAnnouncement(
        View.of(context),
        'Não foi possível reconhecer. Toque em Tentar novamente.',
        TextDirection.ltr,
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: DesignTokens.colorSurfaceBg,
      body: Center(
        child: Padding(
          padding: DesignTokens.screenPadding,
          // `liveRegion: true` so a screen reader announces the subtree's
          // content whenever it changes — in particular the "autenticando"
          // -> retry-button transition below (_showRetry flipping true),
          // instead of staying silent about that state change.
          child: Semantics(
            liveRegion: true,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                const Icon(
                  Icons.lock_outline,
                  size: DesignTokens.spacing2xl,
                  color: DesignTokens.colorTextSecondary,
                ),
                const SizedBox(height: DesignTokens.spacingMd),
                Text(
                  'Cerne bloqueado',
                  textAlign: TextAlign.center,
                  style: DesignTokens.textHeadlineMd.copyWith(
                    color: DesignTokens.colorTextPrimary,
                  ),
                ),
                const SizedBox(height: DesignTokens.spacingSm),
                Text(
                  'Use a biometria do seu dispositivo para continuar.',
                  textAlign: TextAlign.center,
                  style: DesignTokens.textBodyMd.copyWith(
                    color: DesignTokens.colorTextSecondary,
                  ),
                ),
                if (_showRetry) ...[
                  const SizedBox(height: DesignTokens.spacingLg),
                  AppButton(
                    label: 'Tentar novamente',
                    onPressed: _attemptAuthenticate,
                  ),
                ],
              ],
            ),
          ),
        ),
      ),
    );
  }
}

import 'dart:async';

import 'package:flutter/widgets.dart';
import 'package:go_router/go_router.dart';

import '../di/injection_container.dart';
import '../../features/auth/domain/entities/session_status.dart';
import '../../features/auth/domain/repositories/session_repository.dart';
import '../../features/auth/presentation/cubit/auth_cubit.dart';
import '../../features/auth/presentation/screens/auth_screen.dart';
import '../../features/vault/domain/entities/vault_status.dart';
import '../../features/vault/domain/repositories/vault_repository.dart';
import '../../features/vault/presentation/screens/vault_lock_screen.dart';
import 'placeholder_screens.dart';

/// Every route this app shell resolves — Story 1.6's original set
/// (`/boot`, `/auth`, `/reauth`, `/`, `/meus-registros`, `/planos-de-acao`,
/// `/configuracoes`) plus Epic 2/spec-2-1's `/vault` lock screen. Named
/// constants so no call site retypes a path literal that could drift from
/// the one `GoRouter` below.
abstract final class AppRoutePaths {
  static const boot = '/boot';
  static const auth = '/auth';
  static const reauth = '/reauth';
  static const vaultLock = '/vault';
  static const home = '/';
  static const meusRegistros = '/meus-registros';
  static const planosDeAcao = '/planos-de-acao';
  static const configuracoes = '/configuracoes';
}

/// The epic's ONE `GoRouter`/`redirect` (Boundaries: "never a second
/// competing `redirect`") — composes [VaultRepository.currentStatus] first,
/// then [SessionRepository.currentStatus] (AD-14). Both repositories are
/// taken as parameters (rather than this file reaching into `sl` itself)
/// purely so a test can pass fakes/mocks directly, without touching the
/// global DI container.
///
/// [navigatorKey] is accepted explicitly (rather than letting `GoRouter`
/// generate its own internally) so the caller — `main.dart`'s
/// `ExpiryOverlayHost` — can reach the Navigator's own `BuildContext`
/// through the same, public, documented key instead of reaching into
/// `GoRouter`'s internal `routerDelegate` (not part of its public API).
GoRouter buildAppRouter({
  required VaultRepository vaultRepository,
  required SessionRepository sessionRepository,
  required GlobalKey<NavigatorState> navigatorKey,
}) {
  return GoRouter(
    navigatorKey: navigatorKey,
    initialLocation: AppRoutePaths.boot,
    refreshListenable: _GoRouterRefreshStream([
      vaultRepository.statusStream,
      sessionRepository.statusStream,
    ]),
    redirect: (context, state) =>
        _redirect(vaultRepository, sessionRepository, state),
    routes: [
      GoRoute(
        path: AppRoutePaths.vaultLock,
        builder: (context, state) =>
            VaultLockScreen(vaultRepository: vaultRepository),
      ),
      GoRoute(
        path: AppRoutePaths.boot,
        builder: (context, state) => const BootSplashScreen(),
      ),
      GoRoute(
        path: AppRoutePaths.auth,
        builder: (context, state) => AuthScreen(
          cubit: sl<AuthCubit>(),
          onAuthenticated: (context) => context.go(AppRoutePaths.home),
        ),
      ),
      GoRoute(
        path: AppRoutePaths.reauth,
        builder: (context, state) => const BiometricReauthPlaceholderScreen(),
      ),
      GoRoute(
        path: AppRoutePaths.home,
        builder: (context, state) => const HomeChatPlaceholderScreen(),
      ),
      GoRoute(
        path: AppRoutePaths.meusRegistros,
        builder: (context, state) => const MeusRegistrosPlaceholderScreen(),
      ),
      GoRoute(
        path: AppRoutePaths.planosDeAcao,
        builder: (context, state) => const ActionPlansPlaceholderScreen(),
      ),
      GoRoute(
        path: AppRoutePaths.configuracoes,
        builder: (context, state) => const ConfiguracoesPlaceholderScreen(),
      ),
    ],
  );
}

/// I/O & Edge-Case Matrix:
/// - status not yet known (`null`) -> `/boot`, unless already there.
/// - `unauthenticated` -> `/auth`, unless already there.
/// - `authenticated`/`expired` -> leaves `/boot`/`/auth` for `/`; every
///   other location is left alone *except* `/reauth` while already
///   `authenticated` (bounced home below — `/reauth` is meant to be
///   reached only by the expiry overlay's own explicit navigation while
///   `expired`, code review Story 1.6) — a mid-session expiry never
///   navigates away (Story 1.5 behavior preserved), and the three
///   non-Home destinations stay reachable while `expired`.
///
/// AD-14: Epic 2's `VaultStatus` gate (RF03) is composed first, strictly
/// ahead of every `SessionStatus` check below — the vault gate overrides
/// any location whenever it isn't `unlocked`, and only once it is does the
/// rest of this function (unchanged from Story 1.6) ever run.
String? _redirect(
  VaultRepository vaultRepository,
  SessionRepository sessionRepository,
  GoRouterState state,
) {
  final location = state.matchedLocation;

  // AD-14 — checked before SessionStatus, per Boundaries ("`_redirect`
  // checks `VaultStatus` before `SessionStatus`"). `VaultStatus.locked` is
  // the default from construction (never `null`), so this never waits on
  // an async warm-up the way the `status == null` boot check below does.
  if (vaultRepository.currentStatus != VaultStatus.unlocked) {
    return location == AppRoutePaths.vaultLock
        ? null
        : AppRoutePaths.vaultLock;
  }

  final status = sessionRepository.currentStatus;

  if (status == null) {
    return location == AppRoutePaths.boot ? null : AppRoutePaths.boot;
  }

  if (status == SessionStatus.unauthenticated) {
    return location == AppRoutePaths.auth ? null : AppRoutePaths.auth;
  }

  // status is authenticated or expired.
  // `vaultLock` is included here too: once the vault unlocks while this
  // location is still `/vault` (the normal cold-start path once
  // `authenticate()` succeeds), the same fall-through that already bounces
  // `/boot`/`/auth` to Home applies — `/vault` is never a valid resting
  // place once `VaultStatus.unlocked`.
  if (location == AppRoutePaths.boot ||
      location == AppRoutePaths.auth ||
      location == AppRoutePaths.vaultLock) {
    return AppRoutePaths.home;
  }
  // `/reauth` is a throwaway placeholder standing in for Epic 2's real
  // reauth flow; it should never be sitting open once the session is back
  // to fully `authenticated` (code review, Story 1.6).
  if (location == AppRoutePaths.reauth &&
      status == SessionStatus.authenticated) {
    return AppRoutePaths.home;
  }
  return null;
}

/// Wraps [streams] as a single `Listenable` so `GoRouter`'s
/// `refreshListenable` can re-run [_redirect] on every emission from either
/// one — go_router 18.1.1 exports no `GoRouterRefreshStream` of its own
/// (Code Map), so this is that small local class. Extended by AD-14 to
/// subscribe to both the vault and the session streams (previously just
/// the one session stream), composing them into the one `Listenable`
/// `GoRouter` itself requires (Boundaries: "never a second
/// `GoRouter`/`redirect`").
class _GoRouterRefreshStream extends ChangeNotifier {
  _GoRouterRefreshStream(Iterable<Stream<dynamic>> streams) {
    _subscriptions = [
      for (final stream in streams)
        stream.listen(
          (_) => notifyListeners(),
          // Mirrors `ExpiryOverlayHost`'s and `SessionRepositoryImpl`'s own
          // subscriptions to this same stream — no current implementation
          // ever errors on it, but a future one that did must not surface
          // as an unhandled zone exception here specifically.
          onError: (_, _) {},
        ),
    ];
  }

  late final List<StreamSubscription<dynamic>> _subscriptions;

  @override
  void dispose() {
    for (final subscription in _subscriptions) {
      subscription.cancel();
    }
    super.dispose();
  }
}

import 'package:freezed_annotation/freezed_annotation.dart';

part 'failure.freezed.dart';

/// AD-3 — the one closed `Failure` hierarchy, exactly 14 subtypes: the 13
/// codes from `docs/input/backend/error-taxonomy.md` plus the local-only
/// `malformedResponse` (client-side parse failure, never sent by the
/// backend). Never redefined or subset per feature; every repository method
/// returns `Either<Failure, T>` built from this type (RNF09).
///
/// `retryable` is derived here, once, from the 6 server `retryable:true`
/// codes (AD-4) — no other file re-decides which codes retry.
@freezed
sealed class Failure with _$Failure {
  const factory Failure.authExpired({required String message}) = AuthExpired;
  const factory Failure.authInvalid({required String message}) = AuthInvalid;
  const factory Failure.networkTimeout({required String message}) =
      NetworkTimeout;
  const factory Failure.networkOffline({required String message}) =
      NetworkOffline;
  const factory Failure.validation({required String message}) = Validation;
  const factory Failure.piiCheckFailed({required String message}) =
      PiiCheckFailed;
  const factory Failure.embeddingFailed({required String message}) =
      EmbeddingFailed;
  const factory Failure.aiGenerationTimeout({required String message}) =
      AiGenerationTimeout;
  const factory Failure.notFound({required String message}) = NotFound;
  const factory Failure.rateLimited({required String message}) = RateLimited;
  const factory Failure.exportEmptyPeriod({required String message}) =
      ExportEmptyPeriod;
  const factory Failure.payloadTooLarge({required String message}) =
      PayloadTooLarge;
  const factory Failure.ocrNoText({required String message}) = OcrNoText;

  /// Local-only — the client's own parse-failure detection. `retryable` is
  /// hardcoded `false` for this subtype (AD-3).
  const factory Failure.malformedResponse({required String message}) =
      MalformedResponse;

  const Failure._();

  /// The 6 server `retryable:true` codes (AD-4). Every other code —
  /// including the local `malformedResponse` — is `false`.
  bool get retryable => switch (this) {
        NetworkTimeout() => true,
        NetworkOffline() => true,
        PiiCheckFailed() => true,
        EmbeddingFailed() => true,
        AiGenerationTimeout() => true,
        RateLimited() => true,
        AuthExpired() ||
        AuthInvalid() ||
        Validation() ||
        NotFound() ||
        ExportEmptyPeriod() ||
        PayloadTooLarge() ||
        OcrNoText() ||
        MalformedResponse() =>
          false,
      };

  /// Maps a backend error `code` (`error-taxonomy.md`) to its `Failure`
  /// subtype. An unrecognized code (should never happen — the taxonomy is
  /// closed) falls back to [Failure.malformedResponse] rather than throwing,
  /// so no repository ever lets an unmapped error escape (RNF09).
  factory Failure.fromCode(String code, String message) => switch (code) {
        'AUTH_EXPIRED' => Failure.authExpired(message: message),
        'AUTH_INVALID' => Failure.authInvalid(message: message),
        'NETWORK_TIMEOUT' => Failure.networkTimeout(message: message),
        'NETWORK_OFFLINE' => Failure.networkOffline(message: message),
        'VALIDATION_ERROR' => Failure.validation(message: message),
        'PII_CHECK_FAILED' => Failure.piiCheckFailed(message: message),
        'EMBEDDING_FAILED' => Failure.embeddingFailed(message: message),
        'AI_GENERATION_TIMEOUT' =>
          Failure.aiGenerationTimeout(message: message),
        'NOT_FOUND' => Failure.notFound(message: message),
        'RATE_LIMITED' => Failure.rateLimited(message: message),
        'EXPORT_EMPTY_PERIOD' => Failure.exportEmptyPeriod(message: message),
        'PAYLOAD_TOO_LARGE' => Failure.payloadTooLarge(message: message),
        'OCR_NO_TEXT' => Failure.ocrNoText(message: message),
        _ => Failure.malformedResponse(message: message),
      };
}

