11	
12	/// Covers spec-2-1's I/O & Edge-Case Matrix exactly:
13	/// - biometrics succeed -> `unlocked` emitted, `Right(unit)`.
14	/// - biometrics fail/cancelled/unavailable (`false` or a thrown
15	///   `LocalAuthException`) -> status stays `locked`,
16	///   `Left(Failure.malformedResponse(...))`, no crash.
17	void main() {
18	  late MockLocalAuthentication mockLocalAuthentication;
19	  late VaultRepositoryImpl repository;
20	
21	  setUp(() {
22	    mockLocalAuthentication = MockLocalAuthentication();
23	    repository = VaultRepositoryImpl(
24	      localAuthentication: mockLocalAuthentication,
25	    );
26	  });
