498	+  void _onDigitTap(String digit) {
499	+    if (_digits.length >= PinKeypad.pinLength) {
500	+      // Defensive — the 350ms auto-advance window already clears the
501	+      // buffer before a 5th tap could land, but a very fast double-tap on
502	+      // the same frame must still never overflow past pinLength.
503	+      return;
