505	+    setState(() => _digits.add(digit));
506	+    if (_digits.length == PinKeypad.pinLength) {
507	+      final pin = _digits.join();
508	+      _advanceTimer = Timer(const Duration(milliseconds: 350), () {
509	+        if (!mounted) {
510	+          return;
511	+        }
512	+        setState(_digits.clear);
513	+        widget.onSubmit(pin);
514	+      });
515	+    }
516	+  }
