1	import 'package:flutter/material.dart';
2	import 'package:flutter/semantics.dart';
3	
4	import '../../../../core/design_tokens.dart';
5	import '../../../../core/widgets/app_button.dart';
6	import '../../domain/repositories/vault_repository.dart';
7	import '../widgets/pin_keypad.dart';
8	
9	/// `/vault` — the epic's one lock screen, shown whenever
10	/// `VaultRepository.currentStatus` isn't `VaultStatus.unlocked`
11	/// (`core/navigation/app_router.dart`'s `_redirect`). Auto-triggers the OS
12	/// biometric prompt once in [initState]; a successful
13	/// [VaultRepository.authenticate] call flips `currentStatus` to `unlocked`,
14	/// which — via `statusStream`/`refreshListenable` — re-runs the redirect and
15	/// navigates away from here on its own, so this widget never navigates
16	/// imperatively itself.
17	///
18	/// Story 2.2: every biometric failure (decline/cancel/any OS lockout — the
19	/// generic `authenticate()` catches already cover it, spec-2-2) falls
20	/// through to a real [PinKeypad] + error band, never a second biometric
21	/// "Tentar novamente" affordance (AC2). The "Usar PIN" ghost link reaches
22	/// the same keypad directly, with no error band, before any biometric
23	/// failure has happened. [VaultRepository.submitPin]'s own success emits
24	/// `VaultStatus.unlocked`, same as [VaultRepository.authenticate] — this
25	/// widget navigates away on that exactly the same way, with no branch for
26	/// "which path unlocked it".
27	class VaultLockScreen extends StatefulWidget {
28	  const VaultLockScreen({required this.vaultRepository, super.key});
29	
30	  final VaultRepository vaultRepository;
31	
32	  @override
33	  State<VaultLockScreen> createState() => _VaultLockScreenState();
34	}
35	
36	class _VaultLockScreenState extends State<VaultLockScreen> {
37	  static const _biometricFailureMessage =
38	      'Não foi possível reconhecer — digite seu PIN';
39	
40	  /// No specific copy is given anywhere in `docs/input/` for a PIN
41	  /// mismatch (the I/O matrix only specifies the `Failure` returned) —
42	  /// decided here (Design Notes), mirroring the biometric failure band's
43	  /// own tone.
44	  static const _pinMismatchMessage = 'PIN incorreto. Tente novamente.';
45	
46	  bool _showPinKeypad = false;
47	  String? _errorMessage;
48	
49	  /// Re-entrancy guard for [_submitPin] — [PinKeypad] clears its own
50	  /// buffer and accepts new taps immediately after calling `onSubmit`,
51	  /// before the awaited [VaultRepository.submitPin] below resolves, so a
52	  /// fast second 4-digit entry could otherwise fire a second concurrent
53	  /// call.
54	  bool _submittingPin = false;
55	
56	  @override
57	  void initState() {
58	    super.initState();
59	    _attemptAuthenticate();
60	  }
61	
62	  Future<void> _attemptAuthenticate() async {
63	    final result = await widget.vaultRepository.authenticate();
64	    if (!mounted) {
65	      return;
66	    }
67	
68	    // On success, `currentStatus` is already `unlocked` and the router's
69	    // own `refreshListenable` will navigate away from `/vault` on its own —
70	    // this widget has nothing further to do (and may already be in the
71	    // process of being disposed by the time that happens).
72	    var shouldAnnounceFailure = false;
73	    result.match(
74	      (_) {
75	        // If the user already reached the keypad manually (via "Usar
76	        // PIN") before this pending call resolved, this late failure must
77	        // never clobber whatever the keypad is currently showing — AC2's
78	        // "no second biometric-retry affordance" only concerns the
79	        // biometric view itself, which is no longer on screen.
80	        final alreadyOnKeypad = _showPinKeypad;
81	        shouldAnnounceFailure = !alreadyOnKeypad;
82	        if (!alreadyOnKeypad) {
83	          setState(() {
84	            _showPinKeypad = true;
85	            _errorMessage = _biometricFailureMessage;
86	          });
87	        }
88	      },
89	      (_) {},
90	    );
91	
92	    // `sendAnnouncement()` (see `_announce` below) is honored on both
93	    // Android and iOS — this app is iOS-only, where VoiceOver doesn't
94	    // reliably treat a live-region subtree update as an announcement on
95	    // its own, so the biometric->PIN transition is spoken explicitly
96	    // here rather than relying on any ambient live region.
97	    if (shouldAnnounceFailure && mounted) {
98	      await _announce(_biometricFailureMessage);
99	    }
100	  }
101	
102	  void _useManualPin() {
103	    setState(() {
104	      _showPinKeypad = true;
105	      _errorMessage = null;
106	    });
107	  }
108	
109	  Future<void> _submitPin(String pin) async {
110	    if (_submittingPin) {
111	      return;
112	    }
113	    _submittingPin = true;
114	    try {
115	      final result = await widget.vaultRepository.submitPin(pin);
116	      if (!mounted) {
117	        return;
118	      }
119	      if (result.isLeft()) {
120	        // Mismatch: stays locked, no attempt cap — the keypad itself has
121	        // already cleared its own buffer by the time this runs
122	        // (PinKeypad's own contract), so the user can simply try again.
123	        setState(() => _errorMessage = _pinMismatchMessage);
124	        await _announce(_pinMismatchMessage);
125	      }
126	      // On a match (first-use or later), `currentStatus` is already
127	      // `unlocked` and the router navigates away on its own, same as a
128	      // successful `authenticate()`.
129	    } finally {
130	      _submittingPin = false;
131	    }
132	  }
133	
134	  Future<void> _announce(String message) async {
135	    if (!mounted) {
136	      return;
137	    }
138	    await SemanticsService.sendAnnouncement(
139	      View.of(context),
140	      message,
141	      TextDirection.ltr,
142	    );
143	  }
144	
145	  @override
146	  Widget build(BuildContext context) {
147	    return Scaffold(
148	      backgroundColor: DesignTokens.colorSurfaceBg,
149	      body: Center(
150	        child: Padding(
151	          padding: DesignTokens.screenPadding,
152	          // No ambient `Semantics(liveRegion: true)` wrapper here — it
